/* eslint-disable @stencil-community/required-jsdoc */
import { Component, Element, h, Prop, Host, ComponentInterface } from '@stencil/core';
import { Dayjs } from 'dayjs';
import {
  DateComparisonPresetShortcut,
  DatePickerViewMode,
  DatePresetOptions,
  DatePresetShortcut,
  DatePresetShortcutStrict,
  NormalizedDatePickerComparisonProps,
} from '../../types';
import { Placement } from '@floating-ui/dom';
import { dateValueToDayjs, i18nRelativeTime } from '../../utils';
import { dateMessages, datePickerMessages } from '@fe-infra/keystone-locales';
import { t } from '@src/shared/i18n';
import { globalConfigStore } from '@src/shared/stores';
import { TimezoneInfo } from '@src/shared/timezone';
import { asObject } from '@src/shared/type-utils';
import { getComparisonPresetValue } from './utils';
const prefix = 'date-presets';

/**
 * The DateTimePickerBase component serves two primary purposes:
 * 1. Normalization: It normalizes external prop values into a consistent internal format for use by internal components.
 * 2. Composition: It assembles and orchestrates the various internal components (e.g., Calendar, TimePanel) that constitute the complete date-time picker.
 */
@Component({
  tag: 'ks-date-time-picker-presets',
  styleUrl: 'index.scss',
  shadow: true,
})
export class KsDateTimePickerPresets implements ComponentInterface {
  @Element() el!: HTMLKsDateTimePickerPresetsElement;

  @Prop() value!: [Dayjs | null, Dayjs | null];
  @Prop() timezone!: TimezoneInfo;
  /** If true, the presenter will display two input fields for a range. If false, a single input field is displayed. */
  @Prop() isRange!: boolean;
  @Prop() now!: Dayjs;
  /** If true, the input field(s) will be disabled and non-interactive. */
  @Prop() disabled!: [boolean, boolean];
  @Prop() comparison!: NormalizedDatePickerComparisonProps;
  /** If true, a clear button is shown when the input has a value and is focused, allowing the user to clear the content. */

  @Prop() open!: boolean;
  @Prop() defaultOpen = false;
  @Prop() setValue!: (value: [Dayjs | null, Dayjs | null], preset: { key?: DatePresetShortcutStrict }) => void;

  /** The placement of the popover relative to the picker input. */
  @Prop() placement: Placement = 'bottom-start';

  @Prop() availableViewModes: DatePickerViewMode[] = ['dateInMonth', 'monthInYear', 'yearInDecade'];

  @Prop() presets!: true | { options: DatePresetOptions };

  @Prop() overridePreset?: DatePresetShortcut[];

  @Prop() isSelectingComparisonValue!: boolean;
  @Prop() setComparison!: (
    comparison: NormalizedDatePickerComparisonProps,
    preset: { key?: DateComparisonPresetShortcut },
  ) => void;

  @Prop() viewMode!: DatePickerViewMode;
  @Prop() handleViewChange!: (viewDate: Dayjs, viewMode: DatePickerViewMode) => void;

  @Prop() disabledDate!: (
    date: Dayjs,
    info: { type: 'date' | 'preset'; from?: Dayjs; to?: Dayjs; selectionPhase?: 'start' | 'end' },
  ) => boolean;

  @Prop() setPresetPreviewDate!: (previewDate: [Dayjs | null, Dayjs | null] | null) => void;

  @Prop() normalizedFormat!: string;

  get locale() {
    return globalConfigStore.state.locale;
  }

  private getLastNDaysPreset(days: number): [Dayjs, Dayjs] {
    const endDate = days ? this.now.subtract(1, 'day') : this.now;
    return [this.now.subtract(days, 'day'), endDate];
  }
  private getLastNWeeksPreset(weeks: number): [Dayjs, Dayjs] {
    // Assumes dayjs locale is set correctly for week start
    let startDayOfWeek = this.now.startOf('week');
    let endDayOfWeek: Dayjs;
    if (weeks > 1) {
      startDayOfWeek = startDayOfWeek.subtract(weeks, 'week');
      endDayOfWeek = this.now.endOf('week').subtract(1, 'week');
    } else if (weeks !== 0) {
      // weeks === 1
      startDayOfWeek = startDayOfWeek.subtract(weeks, 'week');
      endDayOfWeek = startDayOfWeek.endOf('week');
    } else {
      // weeks === 0
      endDayOfWeek = this.now;
    }
    return [startDayOfWeek, endDayOfWeek];
  }
  private getLastNMonthsPreset(months: number): [Dayjs, Dayjs] {
    let startDayOfMonth = this.now.startOf('month');
    let endDayOfMonth: Dayjs;
    if (months > 1) {
      startDayOfMonth = startDayOfMonth.subtract(months, 'month');
      endDayOfMonth = this.now.endOf('month').subtract(1, 'month');
    } else if (months !== 0) {
      // months === 1
      startDayOfMonth = startDayOfMonth.subtract(months, 'month');
      endDayOfMonth = startDayOfMonth.endOf('month');
    } else {
      // months === 0
      endDayOfMonth = this.now;
    }
    return [startDayOfMonth, endDayOfMonth];
  }

  // eslint-disable-next-line max-lines-per-function
  private getQuickOptionPreset() {
    let preset: {
      key?: DatePresetShortcutStrict | DateComparisonPresetShortcut;
      label: string;
      value: [Dayjs | null, Dayjs | null];
    }[];

    if (this.isSelectingComparisonValue) {
      preset = (this.comparison.presetOptions || ['period_over_period', 'year_over_year', 'month_over_month']).map(
        (item) =>
          typeof item === 'string'
            ? {
                key: item,
                // TODO i18n
                label:
                  item === 'period_over_period'
                    ? t(dateMessages.pickerComparisonPreviousPeriod)
                    : item === 'year_over_year'
                      ? t(dateMessages.pickerComparisonPreviousYear)
                      : t(dateMessages.pickerComparisonPreviousMonth),
                value: getComparisonPresetValue(this.value, item),
              }
            : {
                label: item.label,
                value: item.value.map((dateValue) =>
                  dateValue ? dateValueToDayjs(dateValue, this.normalizedFormat, this.timezone) : null,
                ) as [Dayjs | null, Dayjs | null],
              },
      );
    } else {
      const options = asObject(this.presets)?.options || [
        'today',
        'yesterday',
        'last_7_days',
        'last_14_days',
        'last_30_days',
        'this_week',
        'last_week',
        'this_month',
        'last_month',
      ];

      preset = options
        // @ts-expect-error "Not all code paths return a value." is expected for more accurate condition flow control
        // eslint-disable-next-line max-lines-per-function
        .map((item) => {
          if (item === 'today') {
            return {
              key: 'today',
              label: i18nRelativeTime(0, 'days', this.locale),
              value: this.getLastNDaysPreset(0),
            } as const;
          } else if (item === 'yesterday') {
            return {
              key: 'yesterday',
              label: i18nRelativeTime(-1, 'days', this.locale),
              value: this.getLastNDaysPreset(1),
            } as const;
          } else if (item === 'tomorrow') {
            return {
              key: 'tomorrow',
              label: i18nRelativeTime(1, 'days', this.locale),
              value: Array(2).fill(this.now.add(1, 'day')),
            } as const;
          } else if (item === 'this_week') {
            return {
              key: 'this_week',
              label: i18nRelativeTime(0, 'weeks', this.locale),
              value: this.getLastNWeeksPreset(0),
            } as const;
          } else if (item === 'last_week') {
            return {
              key: 'last_week',
              label: i18nRelativeTime(-1, 'weeks', this.locale),
              value: this.getLastNWeeksPreset(1),
            } as const;
          } else if (item === 'next_week') {
            return {
              key: 'next_week',
              label: i18nRelativeTime(1, 'weeks', this.locale),
              value: this.getLastNWeeksPreset(-1),
            } as const;
          } else if (item === 'this_month') {
            return {
              key: 'this_month',
              label: i18nRelativeTime(0, 'months', this.locale),
              value: this.getLastNMonthsPreset(0),
            } as const;
          } else if (item === 'last_month') {
            return {
              key: 'last_month',
              label: i18nRelativeTime(-1, 'months', this.locale),
              value: this.getLastNMonthsPreset(1),
            } as const;
          } else if (item === 'next_month') {
            return {
              key: 'next_month',
              label: i18nRelativeTime(1, 'months', this.locale),
              value: this.getLastNMonthsPreset(-1),
            } as const;
          } else if (typeof item === 'string') {
            const lastMatch = item.match(/^last_(\d+)_(days|weeks|months)$/);
            if (lastMatch) {
              const n = parseInt(lastMatch[1]!, 10);
              const unit = lastMatch[2]! as 'days' | 'weeks' | 'months';
              if (unit === 'days') {
                return {
                  key: item as DatePresetShortcutStrict,
                  label:
                    n <= 1 ? i18nRelativeTime(-n, 'days', this.locale) : t(datePickerMessages.lastNDays, { days: n }),
                  value: this.getLastNDaysPreset(n),
                } as const;
              } else if (unit === 'weeks') {
                return {
                  key: item as DatePresetShortcutStrict,
                  label: i18nRelativeTime(-n, 'weeks', this.locale),
                  value: this.getLastNWeeksPreset(n),
                } as const;
              } else {
                return {
                  key: item as DatePresetShortcutStrict,
                  label:
                    n <= 1
                      ? i18nRelativeTime(-n, 'months', this.locale)
                      : t(datePickerMessages.lastNMonths, { months: n }),
                  value: this.getLastNMonthsPreset(n),
                } as const;
              }
            }

            const nextMatch = typeof item === 'string' ? item.match(/^next_(\d+)_(days|weeks|months)$/) : null;
            if (nextMatch) {
              const n = parseInt(nextMatch[1]!, 10);
              const unit = nextMatch[2]! as 'days' | 'weeks' | 'months';
              if (unit === 'days') {
                const start = this.now.add(1, 'day');
                const end = this.now.add(n, 'day');
                return {
                  key: item as DatePresetShortcutStrict,
                  label: i18nRelativeTime(n, 'days', this.locale),
                  value: [start, end],
                } as const;
              } else if (unit === 'weeks') {
                if (n === 1) {
                  return {
                    key: item as DatePresetShortcutStrict,
                    label: i18nRelativeTime(1, 'weeks', this.locale),
                    value: this.getLastNWeeksPreset(-1),
                  } as const;
                }
                const start = this.now.startOf('week').add(1, 'week');
                const end = this.now.endOf('week').add(n, 'week');
                return {
                  key: item as DatePresetShortcutStrict,
                  label: i18nRelativeTime(n, 'weeks', this.locale),
                  value: [start, end],
                } as const;
              } else {
                if (n === 1) {
                  return {
                    key: item as DatePresetShortcutStrict,
                    label: i18nRelativeTime(1, 'months', this.locale),
                    value: this.getLastNMonthsPreset(-1),
                  } as const;
                }
                const start = this.now.startOf('month').add(1, 'month');
                const end = this.now.endOf('month').add(n, 'month');
                return {
                  key: item as DatePresetShortcutStrict,
                  label: i18nRelativeTime(n, 'months', this.locale),
                  value: [start, end],
                } as const;
              }
            }
          } else if (typeof item === 'object') {
            const value = [
              Array.isArray(item.value) ? item.value[0] : item.value,
              Array.isArray(item.value) ? item.value[1] || item.value[0] : item.value,
            ];
            return {
              key: item.key,
              label: item.label,
              value: value.map((dateValue) =>
                dateValue ? dateValueToDayjs(dateValue, this.normalizedFormat, this.timezone) : null,
              ) as [Dayjs | null, Dayjs | null],
            };
          }
        })
        .filter(Boolean) as typeof preset;
    }

    return preset;
  }

  render() {
    return (
      <Host>
        <div class={prefix}>
          {this.getQuickOptionPreset().map((option) => {
            const [startDay, endDay] = option.value;
            const compareWith = this.isSelectingComparisonValue ? this.comparison.value : this.value;
            const selected = Boolean(
              Array.isArray(compareWith) &&
              compareWith[0]?.isSame(startDay, 'day') &&
              compareWith[1]?.isSame(endDay, 'day'),
            );
            const disabled =
              this.disabled?.[0] ||
              this.disabled?.[1] ||
              Boolean(
                (startDay && this.disabledDate(startDay, { type: 'preset', to: endDay || undefined })) ||
                (endDay && this.disabledDate(endDay, { type: 'preset', from: startDay || undefined })),
              );

            const onClick = disabled
              ? undefined
              : () => {
                  if (this.isSelectingComparisonValue) {
                    this.setComparison(
                      {
                        ...this.comparison,
                        value: [startDay, endDay],
                      },
                      { key: option.key as DateComparisonPresetShortcut },
                    );
                  } else {
                    this.setValue([startDay, endDay], { key: option.key as DatePresetShortcutStrict });
                  }

                  const targetViewDate = startDay || endDay;
                  if (targetViewDate) {
                    this.handleViewChange(targetViewDate, this.viewMode);
                  }
                };

            const onPointerEnter = disabled ? undefined : () => this.setPresetPreviewDate([startDay, endDay]);
            const onPointerLeave = disabled ? undefined : () => this.setPresetPreviewDate(null);

            return (
              <div
                class={{
                  [`${prefix}__option`]: true,
                  [`${prefix}__option--selected`]: selected,
                  [`${prefix}__option--disabled`]: disabled,
                }}
                onPointerEnter={onPointerEnter}
                onPointerLeave={onPointerLeave}
                onClick={onClick}
                data-testid="presets-index-naBbHs"
              >
                {option.label}
              </div>
            );
          })}
        </div>
      </Host>
    );
  }
}
